  (function () {
    var w = window, r = document.documentElement;
    /* ===== MOTION SETTINGS — set any feature to false to turn it off ===== */
    w.MOTION = {
      preloader: true,     /* logo-draw intro, shown once per browser session */
      aurora: true,        /* drifting colour glow behind the hero */
      grid: true,          /* slow moving grid lines in the hero */
      particles: true,     /* interactive particle network (auto-off on slow devices) */
      shapes: true,        /* floating geometric shapes in the hero */
      spotlight: true,     /* soft light that follows the mouse over the hero */
      wave: true,          /* animated wave where the hero meets the page */
      words: true,         /* headline reveals word by word */
      parallax: true,      /* 3D tilt of the template collage */
      stats: true,         /* live counters (template + category count from your blog feed) */
      reveal: true,        /* fade-and-rise as sections scroll into view */
      cardTilt: true,      /* 3D tilt and glare on template cards */
      magnetic: true,      /* buttons lean toward the cursor */
      ripple: true,        /* click ripple on buttons */
      navPill: true,       /* sliding highlight in the main menu */
      headerHide: true,    /* header slides away on scroll down, returns on scroll up */
      topRing: true,       /* scroll-progress ring on the back-to-top button */
      marquee: true,       /* scrolling feature ribbon under the features strip */
      lightbox: true,      /* click a post image to enlarge it */
      tocSpy: true         /* highlight the current section in the table of contents */
    };
    var calm = false;
    try { calm = !!(w.matchMedia && w.matchMedia('(prefers-reduced-motion: reduce)').matches); } catch (e) {}
    if (!calm) {
      r.classList.add('js');
      try { if (w.MOTION.preloader && !sessionStorage.getItem('pos-intro')) { r.classList.add('pl'); } } catch (e) {}
    }
    if (!r.classList.contains('pl')) { r.classList.add('go'); }
    /* safety net: if the motion script never starts, show the plain site */
    setTimeout(function () { if (!w.__mo) { r.classList.remove('js', 'pl'); r.classList.add('go'); } }, 4500);
  })();
//

head.b:skin:
/* ==========================================================
   Purna Online Solution — Blogger template skin
   ========================================================== */
:root{
  --navy:#061046; --navy-2:#0a1a63; --blue:#1565ff; --blue-2:#0ea5e9; --violet:#6d28d9; --cyan:#22d3ee; --yellow:#fbbf24;
  --ink:#0d1b4c; --text:#3b4a6b; --muted:#6b7a99; --line:#e3e9f6; --bg:#f2f5fc; --card:#fff;
  --grad:linear-gradient(135deg,#0b3fe0 0%,#1a74ff 55%,#12a8f0 100%);
  --hero:linear-gradient(115deg,#06145f 0%,#0a2bb5 46%,#5b2bd1 100%);
  --r:16px; --r-sm:10px; --shadow:0 14px 34px -16px rgba(14,40,120,.35); --shadow-sm:0 4px 14px -6px rgba(14,40,120,.22);
  --w:1320px; --ease:cubic-bezier(.22,1,.36,1);
  --font:'Poppins',system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif;
}
*,*::before,*::after{box-sizing:border-box}
html{scroll-behavior:smooth;-webkit-text-size-adjust:100%}
body{margin:0;background:var(--bg);color:var(--text);font:400 15px/1.7 var(--font);min-height:100vh;min-height:100dvh;overflow-x:hidden}
img,svg,video,iframe{max-width:100%}
img{height:auto;display:block}
a{color:inherit;text-decoration:none}
ul,ol{margin:0;padding:0;list-style:none}
h1,h2,h3,h4{margin:0;color:var(--ink);line-height:1.25;font-weight:700}
button,input{font:inherit}
.ic{width:1.1em;height:1.1em;flex:none;stroke:currentColor;fill:none;stroke-width:2;stroke-linecap:round;stroke-linejoin:round;vertical-align:-.16em}
.ic.f{fill:currentColor;stroke:none}
.container{width:min(100% - 2.5rem,var(--w));margin-inline:auto}
.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0 0 0 0);white-space:nowrap}
.skip{position:absolute;left:1rem;top:-4rem;background:#fff;color:var(--ink);padding:.6rem 1rem;border-radius:8px;z-index:999;box-shadow:var(--shadow)}
.skip:focus{top:1rem}
:focus-visible{outline:3px solid var(--cyan);outline-offset:2px;border-radius:6px}
.widget{margin:0}
.section{margin:0}

/* ---------- Top bar ---------- */
.topbar{background:linear-gradient(90deg,#0a3cd8,#0f7be8 55%,#10a6ee);color:#fff;font-size:13px;font-weight:500}
.topbar .container{display:flex;align-items:center;justify-content:space-between;gap:1rem;min-height:36px}
.topbar .tb-msg{display:flex;align-items:center;gap:.5rem}
.topbar .tb-right{display:flex;align-items:center;gap:1rem}
.topbar .tb-links a:hover{text-decoration:underline}
.topbar .tb-sep{width:1px;height:18px;background:rgba(255,255,255,.55)}
.social{display:flex;gap:.45rem}
.social a{width:22px;height:22px;border-radius:50%;display:grid;place-items:center;color:#fff;transition:transform .25s var(--ease)}
.social a:hover{transform:translateY(-2px) scale(1.08)}
.social .fb{background:#1877f2}.social .yt{background:#ff0000}.social .tw{background:#1d9bf0}.social .ig{background:linear-gradient(45deg,#f9a03f,#e1306c 55%,#833ab4)}
.social .ic{width:12px;height:12px}
.topbar .widget-content{display:contents}

/* ---------- Header ---------- */
.site-header{position:sticky;top:0;z-index:100;background:#fff;box-shadow:0 1px 0 var(--line);transition:box-shadow .3s}
.site-header.is-stuck{box-shadow:0 10px 30px -14px rgba(10,30,100,.35)}
.site-header .container{display:flex;align-items:center;gap:1.5rem;min-height:64px}
.logo{display:flex;align-items:center;gap:.65rem;flex:none}
.logo .mark{width:42px;height:42px}
.logo .name{display:block;font-size:22px;font-weight:700;letter-spacing:-.01em;line-height:1.05;background:linear-gradient(90deg,#0a3cd8,#1d8cf0);-webkit-background-clip:text;background-clip:text;color:transparent}
.logo .tagline{display:block;font-size:12px;color:#8391b2;font-weight:500;letter-spacing:.02em;margin-top:2px}
.logo .tagline b{color:var(--ink);font-weight:500}.logo .tagline i{font-style:normal;color:#7bd35c}
.logo-wrap{margin:0}
.main-nav{flex:1;display:flex;justify-content:center}
.main-nav>ul,.main-nav ul.menu{display:flex;align-items:center;gap:.25rem}
.main-nav li{position:relative}
.main-nav a{display:flex;align-items:center;gap:.4rem;padding:.55rem .95rem;border-radius:10px;font-weight:600;font-size:14.5px;color:var(--ink);transition:background .2s,color .2s}
.main-nav a:hover,.main-nav li:focus-within>a{color:var(--blue);background:#eef3ff}
.main-nav a.active{background:var(--grad);color:#fff;box-shadow:0 8px 18px -8px rgba(21,101,255,.7)}
.main-nav .ic.chev{width:.8em;height:.8em;transition:transform .25s var(--ease)}
.main-nav li:hover>a .chev{transform:rotate(180deg)}
.main-nav .sub{position:absolute;left:0;top:calc(100% + 6px);min-width:210px;background:#fff;border:1px solid var(--line);border-radius:14px;padding:.45rem;box-shadow:var(--shadow);opacity:0;visibility:hidden;transform:translateY(8px);transition:opacity .2s,transform .25s var(--ease),visibility .2s;z-index:50}
.main-nav li:hover>.sub,.main-nav li:focus-within>.sub{opacity:1;visibility:visible;transform:none}
.main-nav .sub a{font-weight:500;font-size:14px;padding:.5rem .8rem}
.search-box{display:flex;flex:none;width:280px;border:1px solid var(--line);border-radius:10px;overflow:hidden;background:#f6f8fd;transition:border-color .2s,box-shadow .2s}
.search-box:focus-within{border-color:var(--blue);box-shadow:0 0 0 3px rgba(21,101,255,.15);background:#fff}
.search-box input{flex:1;min-width:0;border:0;background:transparent;padding:.6rem .9rem;color:var(--ink);outline:0;font-size:14px}
.search-box button{border:0;background:var(--grad);color:#fff;width:46px;cursor:pointer;display:grid;place-items:center}
.search-box button:hover{filter:brightness(1.08)}
.nav-toggle{display:none;margin-left:auto;width:44px;height:44px;border:1px solid var(--line);border-radius:12px;background:#fff;color:var(--ink);cursor:pointer;place-items:center}
.nav-toggle .ic{width:22px;height:22px}

/* ---------- Hero ---------- */
.hero{position:relative;background:var(--hero);color:#fff;overflow:hidden;padding:3.2rem 0 8.5rem}
.hero::before,.hero::after{content:'';position:absolute;pointer-events:none;background-image:radial-gradient(rgba(255,255,255,.5) 1.6px,transparent 1.8px);background-size:15px 15px;opacity:.35}
.hero::before{left:-10px;top:60px;width:150px;height:150px;-webkit-mask-image:radial-gradient(circle at 30% 30%,#000,transparent 70%);mask-image:radial-gradient(circle at 30% 30%,#000,transparent 70%)}
.hero::after{right:2%;top:70px;width:170px;height:170px;border-radius:50%;-webkit-mask-image:radial-gradient(circle,#000 30%,transparent 72%);mask-image:radial-gradient(circle,#000 30%,transparent 72%)}
.hero .container{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);align-items:center;gap:2rem;position:relative;z-index:1}
.hero-pill{display:inline-flex;align-items:center;background:linear-gradient(90deg,#4f46e5,#6d5cf5);padding:.35rem 1.1rem;border-radius:999px;font-size:14px;font-weight:600;margin-bottom:1.1rem}
.hero h1{color:#fff;font-size:clamp(2rem,4.2vw,3.35rem);font-weight:700;letter-spacing:-.02em;line-height:1.12;margin-bottom:1rem}
.hero h1 em{font-style:normal;color:var(--cyan)}
.hero .lead{font-size:clamp(1rem,1.5vw,1.2rem);color:#e2e8ff;max-width:34em;margin:0 0 1.3rem}
.hero-feats{display:flex;flex-wrap:wrap;gap:.8rem 1.5rem;margin-bottom:1.6rem;font-weight:500;font-size:14px}
.hero-feats span{display:flex;align-items:center;gap:.5rem}
.hero-feats .ic{width:24px;height:24px}
.hero-feats .c1{color:#ffb020}.hero-feats .c2{color:#ffd23f}.hero-feats .c3{color:#cfe0ff}.hero-feats .c4{color:#ffc53d}
.hero-cta{display:flex;flex-wrap:wrap;gap:.9rem}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:.6rem;border-radius:999px;font-weight:600;font-size:15px;padding:.8rem 1.6rem;border:2px solid transparent;cursor:pointer;transition:transform .25s var(--ease),box-shadow .25s,background .25s}
.btn:hover{transform:translateY(-2px)}
.btn-primary{background:linear-gradient(90deg,#1d6bff,#10a2f2);color:#fff;box-shadow:0 12px 24px -10px rgba(14,165,233,.9)}
.btn-outline{border-color:rgba(255,255,255,.75);color:#fff;background:rgba(255,255,255,.04)}
.btn-outline:hover{background:rgba(255,255,255,.14)}
.btn-white{background:#fff;color:var(--blue);padding:.45rem 1.4rem;font-size:14px}

/* Collage of template previews (pure CSS) */
.hero-art{position:relative;height:390px;perspective:1400px}
.mk{position:absolute;left:var(--x);top:var(--y);width:var(--w,260px);aspect-ratio:16/10.5;background:#fff;border-radius:10px;padding:0 0 6px;box-shadow:0 24px 40px -14px rgba(3,8,50,.7),0 0 0 1px rgba(255,255,255,.35);transform:rotateX(14deg) rotateY(-16deg) rotateZ(var(--r));z-index:var(--z);overflow:hidden;animation:mkIn .9s var(--ease) both;animation-delay:var(--d,0s)}
.mk-bar{display:block;height:14px;background:#f1f4fb;position:relative}
.mk-bar::before{content:'';position:absolute;left:6px;top:5px;width:4px;height:4px;border-radius:50%;background:#ff6b6b;box-shadow:7px 0 #ffd23f,14px 0 #3ddc84}
.mk-hero{display:block;margin:5px;height:42%;border-radius:5px;background:linear-gradient(120deg,var(--c1),var(--c2));position:relative}
.mk-hero::after{content:'';position:absolute;left:10px;bottom:10px;width:46%;height:6px;border-radius:3px;background:rgba(255,255,255,.75);box-shadow:0 -10px 0 -1px rgba(255,255,255,.45)}
.mk-row{display:grid;grid-template-columns:repeat(4,1fr);gap:4px;margin:0 5px}
.mk-row b{display:block;aspect-ratio:1;border-radius:4px;background:linear-gradient(140deg,var(--c2),var(--c1));opacity:.9}
.mk-row b:nth-child(2){filter:hue-rotate(60deg)}.mk-row b:nth-child(3){filter:hue-rotate(150deg)}.mk-row b:nth-child(4){filter:hue-rotate(250deg)}
@keyframes mkIn{from{opacity:0;translate:0 40px}to{opacity:1;translate:0 0}}
@keyframes floaty{50%{translate:0 -8px}}
.hero-art .mk:nth-child(odd){animation:mkIn .9s var(--ease) both,floaty 7s ease-in-out 1.2s infinite}
.hero-badge{position:absolute;right:-2%;bottom:6%;z-index:9;transform:rotate(-12deg);width:230px;padding:1.5rem 1.6rem 1.2rem;color:#1a1200;text-align:center;background:linear-gradient(135deg,#ffd23f,#f5a300);clip-path:polygon(2% 14%,12% 4%,30% 9%,52% 2%,74% 8%,93% 3%,99% 22%,95% 46%,100% 70%,92% 92%,70% 97%,48% 92%,26% 99%,6% 93%,0 70%,4% 44%);font-weight:800;font-size:25px;line-height:1.1;letter-spacing:-.01em}
.hero-badge .ic{width:34px;height:34px;display:block;margin:0 auto 2px;color:#1a1200}
.hero-plane{position:absolute;left:4%;top:-2%;width:56px;color:#fff;opacity:.95;z-index:3}
.hero-path{position:absolute;left:-2%;top:2%;width:110px;height:80px;fill:none;stroke:rgba(255,255,255,.7);stroke-width:1.5;stroke-dasharray:4 5}

/* ---------- Content layout ---------- */
.layout{display:grid;grid-template-columns:minmax(0,1fr);gap:28px;align-items:start;padding:2rem 0}
.is-home .layout{margin-top:-6.2rem;position:relative;z-index:2;padding-top:0}
.pt-item .layout{grid-template-columns:minmax(0,1fr) 330px}
.sidebar{position:sticky;top:84px;display:grid;gap:20px}

/* ---------- Template cards panel ---------- */
.panel{background:#fff;border-radius:18px;padding:1.4rem 1.4rem 2.6rem;box-shadow:var(--shadow);border:1px solid rgba(227,233,246,.8)}
.panel-head{display:flex;align-items:center;justify-content:space-between;gap:1rem;margin-bottom:1.2rem}
.panel-title{display:flex;align-items:center;gap:.7rem;font-size:clamp(1.2rem,2vw,1.55rem)}
.panel-title::before{content:'';width:4px;height:26px;border-radius:2px;background:var(--grad)}
.panel-link{display:inline-flex;align-items:center;gap:.4rem;font-weight:600;font-size:14px;color:var(--blue)}
.panel-link:hover{text-decoration:underline}
.panel-desc{color:var(--muted);margin:-.6rem 0 1.2rem;font-size:14px}
.tgrid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:18px;row-gap:34px}
.tcard{position:relative;background:#fff;border:1px solid var(--line);border-radius:14px;padding:8px 8px 30px;text-align:center;box-shadow:var(--shadow-sm);transition:transform .35s var(--ease),box-shadow .35s}
.tcard:hover{transform:translateY(-5px);box-shadow:0 22px 34px -18px rgba(14,40,120,.5)}
.tthumb{display:block;border-radius:9px;overflow:hidden;aspect-ratio:16/10;background:linear-gradient(135deg,#dbe5ff,#eef2ff);position:relative}
.tthumb img{width:100%;height:100%;object-fit:cover;transition:transform .6s var(--ease)}
.tcard:hover .tthumb img{transform:scale(1.05)}
.tthumb-empty{display:grid;place-items:center;color:#9bb0e8;font-size:2rem}
.badge-new{position:absolute;right:-6px;top:-8px;background:#f0242f;color:#fff;font-size:12px;font-weight:700;padding:.18rem .85rem;border-radius:999px;box-shadow:0 6px 12px -4px rgba(240,36,47,.6);z-index:2}
.tcard h2{font-size:15.5px;margin:.75rem .2rem .15rem;line-height:1.3}
.tcard h2 a:hover{color:var(--blue)}
.ttags{font-size:12px;color:var(--muted);display:flex;justify-content:center;flex-wrap:wrap;gap:0 .35rem;min-height:1.6em}
.ttags span+span::before{content:'\2022';margin-right:.35rem;color:#b3bdd6}
.btn-dl{position:absolute;left:50%;bottom:-16px;transform:translateX(-50%);display:inline-flex;align-items:center;gap:.4rem;background:var(--grad);color:#fff;font-weight:600;font-size:13.5px;padding:.42rem 1.5rem;border-radius:999px;box-shadow:0 10px 18px -8px rgba(21,101,255,.8);white-space:nowrap;transition:filter .2s,transform .25s var(--ease)}
.btn-dl:hover{filter:brightness(1.1);transform:translateX(-50%) translateY(-2px)}
.feed-ad{grid-column:1/-1}
.pager{display:flex;justify-content:center;gap:.8rem;margin-top:3rem}
.pager a{display:inline-flex;align-items:center;gap:.5rem;padding:.6rem 1.4rem;border-radius:999px;font-weight:600;background:var(--grad);color:#fff}
.pager a.ghost{background:#fff;color:var(--blue);border:1px solid var(--line)}

/* ---------- Features strip + CTA ---------- */
.features{display:grid;grid-template-columns:repeat(5,minmax(0,1fr)) minmax(0,1.6fr);gap:14px;padding:0 0 2.4rem}
.feat{display:flex;align-items:center;gap:.65rem;background:#fff;border-radius:14px;padding:.9rem .9rem;box-shadow:var(--shadow-sm);border:1px solid rgba(227,233,246,.8);transition:transform .3s var(--ease)}
.feat:hover{transform:translateY(-3px)}
.feat .ic{width:36px;height:36px;stroke-width:1.7}
.feat strong{display:block;color:var(--ink);font-size:14px;line-height:1.25}
.feat small{display:block;color:var(--muted);font-size:12.5px;line-height:1.35}
.fi1 .ic{color:#2563eb}.fi2 .ic{color:#22c55e}.fi3 .ic{color:#7c3aed}.fi4 .ic{color:#f59e0b}.fi5 .ic{color:#e11d8d}
.cta{position:relative;display:flex;align-items:center;justify-content:center;gap:1.4rem;background:linear-gradient(110deg,#1536d6,#2c6bff 55%,#7a3fe4);color:#fff;border-radius:14px;padding:1rem 1.6rem;text-align:center;overflow:hidden;box-shadow:var(--shadow)}
.cta::after{content:'';position:absolute;inset:auto -10% -60% auto;width:60%;height:140%;background:radial-gradient(circle,rgba(255,255,255,.18),transparent 65%)}
.cta>.ic{width:64px;height:64px;color:#fff;stroke-width:1.4;flex:none;position:relative;z-index:1}
.cta div{position:relative;z-index:1}
.cta strong{display:block;font-size:17px;font-weight:700;line-height:1.3;margin-bottom:.6rem}

/* ---------- Footer ---------- */
.site-footer{background:linear-gradient(180deg,#071553,#050f3d);color:#cbd5f5;margin-top:1rem;position:relative}
.site-footer::before{content:'';position:absolute;left:0;right:0;top:-1px;height:3px;background:linear-gradient(90deg,#1d6bff,#22d3ee,#7c3aed,#e1306c)}
.ft-grid{display:grid;grid-template-columns:minmax(0,1.35fr) minmax(0,.9fr) minmax(0,1fr) minmax(0,1.35fr);gap:2.4rem;padding:2.6rem 0 2.2rem}
.ft-grid h3{color:#fff;font-size:16px;margin-bottom:1rem}
.ft-brand .logo .name{background:none;color:#fff;-webkit-text-fill-color:#fff}
.ft-brand .logo .tagline,.ft-brand .logo .tagline b{color:#b9c6ee}
.ft-brand p{margin:.9rem 0 1rem;font-size:14.5px;color:#d3dcfa;max-width:26em}
.ft-brand .social a{width:34px;height:34px}.ft-brand .social .ic{width:17px;height:17px}
.ft-links li{margin-bottom:.55rem}
.ft-links a{display:inline-flex;align-items:center;gap:.6rem;font-size:14px;color:#e6ecff;transition:color .2s,transform .25s var(--ease)}
.ft-links a:hover{color:var(--cyan);transform:translateX(3px)}
.ft-news p{display:flex;align-items:center;gap:.6rem;font-size:13.5px;margin:0 0 .9rem;color:#e6ecff}
.nl-form{display:flex;border-radius:8px;overflow:hidden;background:#fff;max-width:420px}
.nl-form input[type=email]{flex:1;min-width:0;border:0;padding:.7rem .9rem;outline:0;color:var(--ink);font-size:14px}
.nl-form button{border:0;background:#1565ff;color:#fff;font-weight:600;padding:0 1.4rem;cursor:pointer;transition:background .2s}
.nl-form button:hover{background:#0f52d6}
.ft-bar{background:#040b30;font-size:13px;color:#c2cdf0}
.ft-bar .container{display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap;padding:.9rem 0}
.ft-bar .ic{color:#ff3b5c;width:1em;height:1em}

/* ---------- Single post ---------- */
.crumbs{font-size:13px;color:var(--muted);margin-bottom:1rem}
.crumbs ol{display:flex;flex-wrap:wrap;gap:.4rem;align-items:center}
.crumbs li{display:inline-flex;gap:.4rem;align-items:center;min-width:0}
.crumbs li+li::before{content:'\203A';opacity:.6}
.crumbs li[aria-current]{max-width:36ch;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.crumbs a:hover{color:var(--blue)}
.article{background:#fff;border-radius:18px;padding:clamp(1.2rem,3.2vw,2.4rem);box-shadow:var(--shadow);border:1px solid rgba(227,233,246,.8)}
.post-tags{display:flex;flex-wrap:wrap;gap:.45rem;margin-bottom:.9rem}
.tag{background:#eef3ff;color:var(--blue);font-weight:600;font-size:12.5px;padding:.2rem .8rem;border-radius:999px;transition:background .2s,color .2s}
.tag:hover{background:var(--blue);color:#fff}
.article h1{font-size:clamp(1.65rem,3.6vw,2.4rem);letter-spacing:-.015em}
.post-meta{display:flex;flex-wrap:wrap;gap:.4rem 1.1rem;color:var(--muted);font-size:13.5px;margin:.9rem 0 1.4rem;padding-bottom:1.1rem;border-bottom:1px solid var(--line)}
.post-meta span,.post-meta time{display:inline-flex;align-items:center;gap:.4rem}
.post-body{font-size:16.5px;line-height:1.85;color:#34425f;overflow-wrap:anywhere}
.post-body>*:first-child{margin-top:0}
.post-body h2,.post-body h3,.post-body h4{margin:2rem 0 .8rem;scroll-margin-top:90px}
.post-body h2{font-size:1.55rem;padding-bottom:.4rem;border-bottom:2px solid #eef3ff}
.post-body h3{font-size:1.25rem}
.post-body p{margin:0 0 1.15rem}
.post-body a{color:var(--blue);text-decoration:underline;text-underline-offset:3px}
.post-body img{border-radius:12px;margin:1rem auto;box-shadow:var(--shadow-sm)}
.post-body ul,.post-body ol{margin:0 0 1.2rem 1.3rem;padding:0}
.post-body ul{list-style:disc}.post-body ol{list-style:decimal}
.post-body li{margin:.3rem 0}
.post-body blockquote{margin:1.4rem 0;padding:1rem 1.3rem;border-left:4px solid var(--blue);background:#f3f7ff;border-radius:0 12px 12px 0;color:var(--ink)}
.post-body pre,.post-body code{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:.88em}
.post-body code{background:#eef3ff;padding:.12em .4em;border-radius:6px}
.post-body pre{position:relative;background:#0b1440;color:#e5ecff;padding:1.1rem 1.2rem;border-radius:12px;overflow:auto;margin:1.3rem 0}
.post-body pre code{background:none;padding:0;color:inherit}
.post-body table{display:block;overflow-x:auto;border-collapse:collapse;width:100%;margin:1.3rem 0}
.post-body th,.post-body td{border:1px solid var(--line);padding:.6rem .9rem;text-align:left}
.post-body th{background:#f3f7ff;color:var(--ink)}
.post-body iframe{width:100%;aspect-ratio:16/9;height:auto;border:0;border-radius:12px}
.post-body .btn-download,.post-body .btn-demo{display:inline-flex;align-items:center;gap:.5rem;text-decoration:none;font-weight:600;padding:.7rem 1.5rem;border-radius:999px;margin:.3rem .5rem .3rem 0}
.post-body .btn-download{background:var(--grad);color:#fff}
.post-body .btn-demo{border:2px solid var(--blue);color:var(--blue)}
.copy-code{position:absolute;right:.6rem;top:.6rem;border:0;background:rgba(255,255,255,.12);color:#fff;font-size:12px;padding:.25rem .7rem;border-radius:8px;cursor:pointer}
.copy-code:hover{background:rgba(255,255,255,.25)}
.toc{background:#f3f7ff;border:1px solid var(--line);border-radius:14px;padding:1rem 1.3rem;margin:0 0 1.6rem}
.toc strong{display:block;color:var(--ink);margin-bottom:.4rem}
.toc ol{list-style:none;margin:0;padding:0}
.toc li{margin:.2rem 0;font-size:14.5px}.toc li.l3{margin-left:1rem;font-size:13.5px}
.toc a{color:var(--text);text-decoration:none}.toc a:hover{color:var(--blue)}
.share-bar{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem;margin:2rem 0 1.4rem;padding-top:1.2rem;border-top:1px solid var(--line)}
.share-btn{border:1px solid var(--line);background:#fff;color:var(--ink);font-weight:600;font-size:13px;padding:.4rem 1rem;border-radius:999px;cursor:pointer;transition:background .2s,color .2s,border-color .2s}
.share-btn:hover{background:var(--blue);color:#fff;border-color:var(--blue)}
.author-box{display:flex;gap:1rem;align-items:center;background:#f3f7ff;border-radius:14px;padding:1rem 1.2rem}
.author-ini{width:48px;height:48px;border-radius:50%;background:var(--grad);color:#fff;display:grid;place-items:center;font-weight:700;flex:none}
.author-box p{margin:.1rem 0 0;font-size:14px}
.post-nav{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin:1.4rem 0}
.post-nav a{display:block;border:1px solid var(--line);border-radius:14px;padding:.9rem 1.1rem;font-weight:600;color:var(--ink);transition:border-color .2s,transform .25s var(--ease)}
.post-nav a:hover{border-color:var(--blue);transform:translateY(-2px)}
.post-nav small{display:block;color:var(--muted);font-weight:500}
.post-nav .next{text-align:right;grid-column:2}
.related h3{margin:1.6rem 0 1rem;font-size:1.25rem}
.related .tgrid{grid-template-columns:repeat(3,minmax(0,1fr))}
.related .tcard{padding-bottom:28px}
.progress{position:fixed;left:0;top:0;height:3px;width:100%;transform:scaleX(0);transform-origin:left;background:linear-gradient(90deg,#1d6bff,#22d3ee,#7c3aed);z-index:200}

/* Sidebar */
.side-card{background:#fff;border-radius:16px;padding:1.2rem;box-shadow:var(--shadow-sm);border:1px solid rgba(227,233,246,.8)}
.side-card h3{font-size:1.05rem;display:flex;align-items:center;gap:.6rem;margin-bottom:.9rem}
.side-card h3::before{content:'';width:4px;height:18px;border-radius:2px;background:var(--grad)}
.side-card .btn{width:100%;margin-bottom:.6rem;padding:.7rem 1rem}
.side-card .btn-demo-s{border:2px solid var(--blue);color:var(--blue);background:#fff}
.chips{display:flex;flex-wrap:wrap;gap:.45rem}
.chips a{background:#eef3ff;color:var(--blue);font-size:13px;font-weight:600;padding:.25rem .8rem;border-radius:999px}
.chips a:hover{background:var(--blue);color:#fff}
.rlist li{display:flex;gap:.8rem;align-items:center;padding:.55rem 0;border-top:1px solid var(--line)}
.rlist li:first-child{border-top:0;padding-top:0}
.rlist img{width:64px;height:48px;object-fit:cover;border-radius:8px;flex:none;background:#e8eeff}
.rlist a{font-weight:600;font-size:14px;line-height:1.35;color:var(--ink)}.rlist a:hover{color:var(--blue)}
.nl-card{background:var(--grad);color:#fff}.nl-card h3,.nl-card p{color:#fff}.nl-card h3::before{background:#fff}
.nl-card p{font-size:14px;margin:0 0 .8rem}

/* Comments */
.comments{margin-top:2rem}
.comments .title{display:block;font-size:1.3rem;margin-bottom:1rem;color:var(--ink);font-weight:700}
.comments ol,.comments ul{list-style:none;margin:0;padding:0}
.comments .comment{display:flex;gap:.75rem;margin-bottom:1rem}
.comments .avatar-image-container{flex:none;width:38px;height:38px;border-radius:50%;overflow:hidden}
.comments .avatar-image-container img{width:100%;height:100%;object-fit:cover;margin:0;box-shadow:none;border-radius:0}
.comments .comment-block{flex:1;background:#f3f7ff;border-radius:12px;padding:.75rem 1rem}
.comments .user{font-weight:700;color:var(--ink)}
.comments .datetime,.comments .comment-timestamp{font-size:.8rem;color:var(--muted)}
.comments .comment-replies{margin:.75rem 0 0 1rem}
.comments .comment-actions a,.comments .footer a{font-size:.85rem;color:var(--blue);font-weight:600;margin-right:.8rem}
.comments iframe{width:100%;border:0}

/* Empty / 404 */
.empty{text-align:center;padding:3rem 1rem}
.empty .code{font-size:clamp(4rem,12vw,7rem);font-weight:800;background:var(--grad);-webkit-background-clip:text;background-clip:text;color:transparent;line-height:1}
.empty h2{margin:.6rem 0 .4rem}.empty p{color:var(--muted);max-width:32em;margin:0 auto 1.4rem}
.empty .btn-primary{display:inline-flex}

.to-top{position:fixed;right:max(1rem,env(safe-area-inset-right));bottom:max(1rem,env(safe-area-inset-bottom));width:46px;height:46px;border-radius:50%;border:0;background:var(--grad);color:#fff;display:grid;place-items:center;cursor:pointer;box-shadow:var(--shadow);opacity:0;visibility:hidden;transform:translateY(10px);transition:opacity .3s,transform .3s var(--ease),visibility .3s;z-index:90}
.to-top.show{opacity:1;visibility:visible;transform:none}
.toast{position:fixed;left:50%;bottom:1.5rem;transform:translate(-50%,20px);background:var(--ink);color:#fff;padding:.6rem 1.2rem;border-radius:999px;font-size:14px;opacity:0;pointer-events:none;transition:opacity .3s,transform .3s var(--ease);z-index:300}
.toast.show{opacity:1;transform:translate(-50%,0)}

/* ---------- Responsive ---------- */
@media (max-width:1180px){
  .tgrid{grid-template-columns:repeat(3,minmax(0,1fr))}
  .features{grid-template-columns:repeat(5,minmax(0,1fr))}.features .cta{grid-column:1/-1}
  .search-box{width:210px}
  .pt-item .layout{grid-template-columns:minmax(0,1fr)}.sidebar{position:static;grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media (max-width:980px){
  .nav-toggle{display:grid}
  .site-header .container{flex-wrap:wrap;gap:.6rem 1rem;padding-block:.5rem}
  .main-nav,.search-box{display:none;width:100%;order:3}
  .nav-open .main-nav{display:block}.nav-open .search-box{display:flex}
  .main-nav>ul,.main-nav ul.menu{flex-direction:column;align-items:stretch;gap:.15rem}
  .main-nav a{padding:.7rem .9rem}
  .main-nav .sub{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:0;padding:0 0 0 .8rem;min-width:0;display:none}
  .main-nav li.open>.sub{display:block}
  .hero{padding:2.2rem 0 7rem}
  .hero .container{grid-template-columns:minmax(0,1fr)}
  .hero-art{height:320px;max-width:560px;margin:0 auto;width:100%}
  .ft-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media (max-width:720px){
  .tgrid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .features{grid-template-columns:repeat(2,minmax(0,1fr))}
  .topbar .tb-links,.topbar .tb-sep{display:none}
  .topbar .tb-msg{font-size:12px}
  .related .tgrid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .sidebar{grid-template-columns:1fr}
  .cta{flex-direction:column;padding:1.2rem}
}
@media (max-width:520px){
  .ft-grid{grid-template-columns:minmax(0,1fr);gap:1.8rem}
  .hero-cta .btn{flex:1 1 100%}
  .hero-art{height:260px}.mk{--w:200px !important}
  .hero-badge{width:170px;font-size:18px;padding:1rem}
  .post-nav{grid-template-columns:1fr}.post-nav .next{grid-column:1;text-align:left}
  .panel{padding:1rem 1rem 2.4rem}
}
@media (pointer:coarse){.main-nav a,.share-btn,.chips a{min-height:44px;display:inline-flex;align-items:center}}
@media (prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
@media print{.topbar,.site-header,.hero,.site-footer,.sidebar,.to-top,.progress,.share-bar,.related,.comments{display:none!important}.article{box-shadow:none;border:0}}

@media (max-width:370px){.tgrid,.related .tgrid{grid-template-columns:minmax(0,1fr)}}

.nav-sec{flex:1;min-width:0}
.is-home .main-nav .menu>li:first-child>a,.main-nav a.active{background:var(--grad);color:#fff;box-shadow:0 8px 18px -8px rgba(21,101,255,.7)}
.ad-area{text-align:center}
.pt-static_page .article{max-width:900px;margin-inline:auto}
@media (max-width:980px){.nav-sec{order:3;flex:1 1 100%}.logo-wrap{flex:1}}


/* ==========================================================
   MOTION LAYER — premium animation system
   Each effect can be switched off in the MOTION object
   (first <script> in <head>). Visitors who prefer reduced
   motion automatically get the calm, static site.
   ========================================================== */
:root{--mo:cubic-bezier(.16,1,.3,1);--spring:cubic-bezier(.34,1.56,.64,1)}

/* ---------- Page transitions (Chrome / Edge / Safari 18+) ---------- */
@view-transition{navigation:auto}
::view-transition-old(root){animation:.2s ease both moVtOut}
::view-transition-new(root){animation:.4s var(--mo) both moVtIn}
@keyframes moVtOut{to{opacity:0}}
@keyframes moVtIn{from{opacity:0}}

/* ---------- Intro: logo draws itself (once per session) ---------- */
.preloader{position:fixed;inset:0;z-index:1000;display:none;place-items:center;background:radial-gradient(120% 90% at 50% 38%,#0a2bb5 0%,#06145f 55%,#030a33 100%);color:#fff;pointer-events:none}
.pl .preloader{display:grid;pointer-events:auto;animation:plOut .5s var(--mo) 2.6s forwards}
.pl-inner{display:grid;justify-items:center;gap:1rem;transition:opacity .3s}
.pl-mark{width:88px;height:88px;overflow:visible;fill:none;stroke-linecap:round;stroke-linejoin:round}
.pl-a{stroke:url(#plg);stroke-width:6.5;stroke-dasharray:1;stroke-dashoffset:1;animation:plDraw 1s var(--mo) .1s forwards}
.pl-b{stroke:#7bd35c;stroke-width:3;stroke-dasharray:1;stroke-dashoffset:1;animation:plDraw .8s var(--mo) .5s forwards}
.pl-dot{fill:#22d3ee;stroke:none;transform-box:fill-box;transform-origin:center;scale:0;animation:plPop .5s var(--spring) .95s forwards}
.pl-name{font-weight:700;font-size:15px;letter-spacing:.04em;opacity:0;animation:plFade .6s ease .7s forwards}
.pl-bar{display:block;width:150px;height:3px;border-radius:3px;background:rgba(255,255,255,.2);overflow:hidden}
.pl-bar i{display:block;height:100%;background:linear-gradient(90deg,#22d3ee,#fff);transform:scaleX(0);transform-origin:left;animation:plBar 1.25s var(--mo) .15s forwards}
.pl.pl-done .preloader{animation:plWipe .85s var(--mo) forwards;pointer-events:none}
.pl.pl-done .pl-inner{opacity:0}
@keyframes plDraw{to{stroke-dashoffset:0}}
@keyframes plPop{to{scale:1}}
@keyframes plFade{to{opacity:1}}
@keyframes plBar{to{transform:scaleX(1)}}
@keyframes plWipe{to{clip-path:inset(0 0 100% 0)}}
@keyframes plOut{to{opacity:0;visibility:hidden}}

/* ---------- Hero: one orchestrated entrance + a living background ---------- */
.js:not(.go) .hero *{animation-play-state:paused!important}
.hero-aurora,.hero-grid,.hero-canvas,.hero-shapes,.hero-wave{position:absolute;pointer-events:none}
.hero-aurora{inset:0;overflow:hidden}
.hero-aurora i{position:absolute;border-radius:50%;filter:blur(70px);mix-blend-mode:screen;will-change:transform;animation:moDrift 18s ease-in-out infinite alternate}
.hero-aurora i:nth-child(1){width:46vw;height:46vw;max-width:640px;max-height:640px;left:-8%;top:-34%;background:#1d6bff;opacity:.4}
.hero-aurora i:nth-child(2){width:38vw;height:38vw;max-width:520px;max-height:520px;right:-6%;top:-24%;background:#8b5cf6;opacity:.36;animation-duration:23s;animation-delay:-6s}
.hero-aurora i:nth-child(3){width:34vw;height:34vw;max-width:460px;max-height:460px;left:38%;bottom:-46%;background:#22d3ee;opacity:.26;animation-duration:27s;animation-delay:-11s}
@keyframes moDrift{0%{transform:translate3d(0,0,0) scale(1)}50%{transform:translate3d(6%,9%,0) scale(1.16)}100%{transform:translate3d(-5%,3%,0) scale(.92)}}
.hero-grid{inset:0;overflow:hidden;-webkit-mask-image:radial-gradient(75% 85% at 50% 38%,#000 20%,transparent 78%);mask-image:radial-gradient(75% 85% at 50% 38%,#000 20%,transparent 78%)}
.hero-grid b{position:absolute;left:0;right:0;top:-56px;bottom:0;background-image:linear-gradient(rgba(255,255,255,.07) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.07) 1px,transparent 1px);background-size:56px 56px;animation:moGrid 9s linear infinite}
@keyframes moGrid{to{translate:0 56px}}
.hero-canvas{inset:0;width:100%;height:100%}
.hero-shapes{inset:0}
.hero-shapes i{position:absolute;left:var(--x);top:var(--y);width:var(--s);height:var(--s);opacity:.55;animation:moBob var(--t,16s) ease-in-out var(--dl,0s) infinite}
.hero-shapes .r{border:2px solid rgba(255,255,255,.55);border-radius:50%}
.hero-shapes .q{border:2px solid rgba(34,211,238,.6);border-radius:7px}
.hero-shapes .t{background:linear-gradient(160deg,rgba(251,191,36,.8),rgba(251,191,36,0));clip-path:polygon(50% 0,100% 100%,0 100%)}
.hero-shapes .p{background:linear-gradient(#fff,#fff) center/100% 2px no-repeat,linear-gradient(#fff,#fff) center/2px 100% no-repeat}
.hero-shapes .d{border-radius:50%;background:radial-gradient(circle at 30% 30%,#fff,rgba(125,211,252,.35))}
@keyframes moBob{0%,100%{translate:0 0;rotate:0deg}50%{translate:0 -20px;rotate:var(--rot,120deg)}}
.hero-spot{position:absolute;left:0;top:0;width:720px;height:720px;margin:-360px 0 0 -360px;border-radius:50%;background:radial-gradient(circle,rgba(125,211,252,.26),transparent 62%);pointer-events:none;opacity:0;transition:opacity .6s;will-change:transform}
.hero:hover .hero-spot{opacity:1}
.hero-wave{left:0;right:0;bottom:-1px;height:72px;overflow:hidden;line-height:0}
.hero-wave svg{position:absolute;left:0;bottom:0;width:200%;height:100%;animation:moWave 16s linear infinite}
.hero-wave svg path{fill:var(--bg)}
.hero-wave svg:nth-child(1){height:82%;animation-duration:26s;animation-direction:reverse}
.hero-wave svg:nth-child(1) path{fill:rgba(242,245,252,.32)}
@keyframes moWave{to{translate:-50% 0}}

/* entrance: words rise out of a mask, everything else follows */
.hero-copy>:not(h1){animation:moUp .85s var(--mo) both}
.hero-copy>:nth-child(1){animation-delay:.1s}
.hero-copy>:nth-child(3){animation-delay:.55s}
.hero-copy>:nth-child(4){animation-delay:.68s}
.hero-copy>:nth-child(5){animation-delay:.8s}
.hero-copy>:nth-child(6){animation-delay:.95s}
@keyframes moUp{from{opacity:0;translate:0 26px}to{opacity:1;translate:0 0}}
.hero h1 .w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .03em .16em;margin:0 -.03em -.16em}
.hero h1 .wi{display:inline-block;transform:translateY(118%) rotate(4deg);transform-origin:0 100%;animation:moWord 1s var(--mo) both;animation-delay:calc(var(--wi,0)*70ms + 200ms)}
@keyframes moWord{to{transform:none}}
.hero h1 em .wi{background:linear-gradient(100deg,#22d3ee 0%,#a5f3fc 28%,#c4b5fd 58%,#22d3ee 100%);background-size:260% 100%;-webkit-background-clip:text;background-clip:text;color:transparent;animation:moWord 1s var(--mo) both,moShine 6s linear infinite;animation-delay:calc(var(--wi,0)*70ms + 200ms),0s}
@keyframes moShine{to{background-position:-260% 0}}
.hero-pill::before{content:'';width:8px;height:8px;border-radius:50%;background:#34d399;margin-right:.55rem;animation:moPing 2.2s ease-out infinite}
@keyframes moPing{0%{box-shadow:0 0 0 0 rgba(52,211,153,.7)}70%,100%{box-shadow:0 0 0 9px rgba(52,211,153,0)}}
.hero-feats span .ic{transition:rotate .5s var(--spring),scale .5s var(--spring)}
.hero-feats span:hover .ic{rotate:-12deg;scale:1.18}
.btn{position:relative;overflow:hidden;transition:transform .25s var(--ease),box-shadow .25s,background .25s,translate .25s var(--mo)}
.btn-primary::after{content:'';position:absolute;top:0;left:0;width:36%;height:100%;background:linear-gradient(100deg,transparent,rgba(255,255,255,.55),transparent);transform:skewX(-20deg);translate:-160% 0;animation:moSheen 4.6s ease-in-out 2.6s infinite;pointer-events:none}
@keyframes moSheen{0%{translate:-160% 0}32%,100%{translate:420% 0}}
.hero-stats{display:flex;flex-wrap:wrap;gap:.6rem 2.2rem;margin-top:1.4rem;padding-top:1rem;border-top:1px solid rgba(255,255,255,.2);max-width:32em}
.hero-stats b{display:block;color:#fff;font-size:clamp(1.35rem,2.2vw,1.8rem);font-weight:700;line-height:1;letter-spacing:-.02em;font-variant-numeric:tabular-nums}
.hero-stats span{display:block;margin-top:.35rem;font-size:12.5px;color:#cdd9ff}

/* collage: parallax tilt (driven by JS), hover lift, living badge */
.hero-art{will-change:transform}
.hero-art .mk{transition:scale .5s var(--mo),box-shadow .5s}
.hero-art .mk:hover{scale:1.05;box-shadow:0 34px 50px -14px rgba(3,8,50,.8),0 0 0 1px rgba(255,255,255,.55)}
.hero-path path{animation:moDash 1.8s linear infinite}
@keyframes moDash{to{stroke-dashoffset:-18}}
.hero-plane{animation:moPlane 7s ease-in-out infinite}
@keyframes moPlane{0%,100%{translate:0 0;rotate:0deg}50%{translate:12px -9px;rotate:-7deg}}
.hero-badge{background:linear-gradient(115deg,#ffd23f 0%,#f5a300 38%,#ffe9a0 50%,#f5a300 62%,#ffd23f 100%);background-size:260% 100%;animation:moFade .8s ease 1.2s both,moBadge 5s ease-in-out 2s infinite,moGloss 5s linear 2s infinite}
@keyframes moFade{from{opacity:0}}
@keyframes moBadge{0%,100%{scale:1}50%{scale:1.05}}
@keyframes moGloss{to{background-position:-260% 0}}

/* ---------- Header, logo and navigation ---------- */
.site-header{transition:box-shadow .3s,translate .45s var(--mo)}
.site-header.hide{translate:0 -100%}
.sidebar{top:var(--sb,84px);transition:top .45s var(--mo)}
.logo .mark{transition:rotate .6s var(--spring),scale .6s var(--spring)}
.logo:hover .mark{rotate:-12deg;scale:1.08}
.logo .name{background-image:linear-gradient(90deg,#0a3cd8,#1d8cf0,#0a3cd8);background-size:200% 100%;animation:moShine 8s linear infinite}
.main-nav{position:relative}
.nav-pill{position:absolute;left:0;top:0;width:0;height:0;border-radius:10px;background:#eef3ff;opacity:0;pointer-events:none;z-index:-1;transition:translate .38s var(--mo),width .38s var(--mo),height .38s var(--mo),opacity .2s}
.nav-pill.on{opacity:1}
.main-nav .menu>li:not(:first-child)>a:not(.active):hover{background:transparent}
.main-nav .sub li{opacity:0;translate:0 8px;transition:opacity .25s,translate .35s var(--mo);transition-delay:calc(var(--n,0)*38ms)}
.main-nav li:hover>.sub li,.main-nav li:focus-within>.sub li{opacity:1;translate:0 0}
.main-nav .sub li:nth-child(1){--n:1}.main-nav .sub li:nth-child(2){--n:2}.main-nav .sub li:nth-child(3){--n:3}.main-nav .sub li:nth-child(4){--n:4}.main-nav .sub li:nth-child(5){--n:5}.main-nav .sub li:nth-child(n+6){--n:6}
@media (max-width:980px){.main-nav .sub li{opacity:1;translate:none}.nav-pill{display:none}}
.search-box{transition:border-color .2s,box-shadow .2s,width .45s var(--mo)}
@media (min-width:1181px){.search-box:focus-within{width:340px}}
.progress{box-shadow:0 0 12px rgba(34,211,238,.75)}
.to-top{overflow:hidden}
.to-top .ring{position:absolute;inset:0;width:100%;height:100%;rotate:-90deg;fill:none;stroke-width:2.5;pointer-events:none}
.to-top .ring .trk{stroke:rgba(255,255,255,.3)}
.to-top .ring .bar{stroke:#fff;stroke-linecap:round;stroke-dasharray:100;stroke-dashoffset:100}
.to-top:hover .ic{animation:moNudge .6s var(--mo)}
@keyframes moNudge{40%{translate:0 -4px}}

/* ---------- Buttons & ripple ---------- */
.pager a,.nl-form button,.search-box button,.share-btn{position:relative;overflow:hidden}
.rip{position:absolute;border-radius:50%;background:currentColor;pointer-events:none;translate:-50% -50%;scale:0;opacity:.28;animation:moRip .65s ease-out forwards}
@keyframes moRip{to{scale:1;opacity:0}}

/* ---------- Scroll reveal (one gentle style, applied by JS) ---------- */
.js .rv{opacity:0;translate:0 26px;transition:opacity .8s var(--mo) calc(var(--i,0)*70ms),translate .9s var(--mo) calc(var(--i,0)*70ms),transform .35s var(--ease),box-shadow .35s}
.js .rv.in{opacity:1;translate:0 0}
.js .tthumb img{opacity:0;scale:1.08;transition:opacity .7s ease,scale 1.1s var(--mo),transform .6s var(--ease)}
.js .tthumb img.ld{opacity:1;scale:1}
.js [data-widget=recent]:empty,.js [data-widget=labels]:empty{min-height:130px;border-radius:10px;background:linear-gradient(100deg,#eef2fb 30%,#f9fbff 50%,#eef2fb 70%) 0 0/300% 100%;animation:moSkel 1.4s linear infinite}
@keyframes moSkel{to{background-position:-200% 0}}

/* ---------- Template cards: tilt, glare, shine ---------- */
.tcard::after{content:'';position:absolute;inset:0;border-radius:14px;pointer-events:none;opacity:0;transition:opacity .3s;background:radial-gradient(240px circle at var(--gx,50%) var(--gy,0%),rgba(255,255,255,.55),transparent 60%)}
.tcard.tilting{transform:perspective(900px) rotateX(var(--rx,0deg)) rotateY(var(--ry,0deg)) translateY(-6px);transition:transform .08s linear,box-shadow .35s}
@media (hover:hover){.tcard:hover::after{opacity:1}}
.btn-dl{overflow:hidden}
.btn-dl::before{content:'';position:absolute;inset:0;background:linear-gradient(100deg,transparent 20%,rgba(255,255,255,.55) 50%,transparent 80%);translate:-120% 0;transition:translate .7s var(--mo);pointer-events:none}
.tcard:hover .btn-dl::before{translate:120% 0}
.badge-new{animation:moPulse 2.4s ease-in-out infinite}
@keyframes moPulse{0%,100%{box-shadow:0 6px 12px -4px rgba(240,36,47,.6)}50%{box-shadow:0 6px 18px 2px rgba(240,36,47,.55)}}
.panel-title::before{transform-origin:top;animation:moBar 1s var(--mo) .2s both}
@keyframes moBar{from{scale:1 0}}
.feat .ic{transition:rotate .5s var(--spring),scale .5s var(--spring)}
.feat:hover .ic{rotate:-10deg;scale:1.15}
.cta{background-image:linear-gradient(110deg,#1536d6,#2c6bff 38%,#7a3fe4 68%,#1536d6);background-size:220% 100%;animation:moGrad 10s ease-in-out infinite alternate}
@keyframes moGrad{to{background-position:100% 0}}
.cta>.ic{animation:moPlane 5s ease-in-out infinite}
.btn-white .ic{transition:translate .3s var(--mo)}
.btn-white:hover .ic{translate:4px 0}

/* ---------- Marquee ribbon ---------- */
.marquee{overflow:hidden;margin:0 0 2.2rem;padding:.85rem 0;border-radius:14px;background:#fff;border:1px solid rgba(227,233,246,.8);box-shadow:var(--shadow-sm);-webkit-mask-image:linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent);mask-image:linear-gradient(90deg,transparent,#000 9%,#000 91%,transparent)}
.mq-track{display:flex;width:max-content;animation:moMarq 40s linear infinite}
.marquee:hover .mq-track{animation-play-state:paused}
.mq-track span{display:inline-flex;align-items:center;gap:.65rem;padding:0 1.7rem;font-weight:600;font-size:14px;color:var(--ink);white-space:nowrap}
.mq-track .ic{width:14px;height:14px;color:#f59e0b}
@keyframes moMarq{to{translate:-50% 0}}

/* ---------- Footer ---------- */
.site-footer::before{background:linear-gradient(90deg,#1d6bff,#22d3ee,#7c3aed,#e1306c,#1d6bff) 0 0/200% 100%;animation:moLine 7s linear infinite}
@keyframes moLine{to{background-position:200% 0}}
.ft-bar .ic{animation:moBeat 1.7s ease-in-out infinite}
@keyframes moBeat{0%,100%{scale:1}14%{scale:1.3}28%{scale:1}42%{scale:1.2}}

/* ---------- Articles ---------- */
.post-body img{cursor:zoom-in}
.post-body h2{position:relative}
.js .post-body h2::after{content:'';position:absolute;left:0;bottom:-2px;height:2px;width:84px;background:var(--grad);transform-origin:left;scale:0 1;transition:scale .9s var(--mo)}
.js .post-body h2.in::after{scale:1 1}
.toc a{position:relative;display:inline-block;transition:color .2s,padding .35s var(--mo)}
.toc a.on{color:var(--blue);font-weight:600;padding-left:.7rem}
.toc a.on::before{content:'';position:absolute;left:0;top:.28em;bottom:.28em;width:3px;border-radius:2px;background:var(--grad)}
.lb{position:fixed;inset:0;z-index:400;display:grid;place-items:center;background:rgba(3,8,40,.86);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);opacity:0;visibility:hidden;transition:opacity .3s,visibility .3s;cursor:zoom-out}
.lb.show{opacity:1;visibility:visible}
.lb img{max-width:min(94vw,1400px);max-height:88vh;width:auto;border-radius:12px;background:#fff;box-shadow:0 30px 80px -20px rgba(0,0,0,.85);scale:.92;transition:scale .5s var(--mo)}
.lb.show img{scale:1}
.lb button{position:absolute;top:max(1rem,env(safe-area-inset-top));right:1rem;width:44px;height:44px;border:0;border-radius:50%;background:rgba(255,255,255,.14);color:#fff;display:grid;place-items:center;cursor:pointer;transition:background .2s,rotate .4s var(--spring)}
.lb button:hover{background:rgba(255,255,255,.28);rotate:90deg}

/* ---------- Small screens, reduced motion, print ---------- */
@media (max-width:720px){
  .hero-aurora i{filter:blur(46px)}
  .hero-shapes{display:none}
  .hero-stats{gap:.6rem 1.5rem}
}
@media (prefers-reduced-motion:reduce){
  @view-transition{navigation:none}
  .preloader{display:none!important}
  .js .rv,.js .tthumb img{opacity:1!important;translate:none!important;scale:1!important}
  .hero h1 .wi{transform:none!important}
}
@media print{.preloader,.lb,.marquee,.hero-aurora,.hero-canvas{display:none!important}}

body.script:
//
(function () {
  'use strict';
  var d = document, root = d.documentElement, body = d.body;
  var $ = function (s, c) { return (c || d).querySelector(s); };
  var $$ = function (s, c) { return Array.prototype.slice.call((c || d).querySelectorAll(s)); };
  var txt = function (el) { return el ? (el.textContent || '').replace(/\s+/g, ' ').trim() : ''; };
  var esc = function (s) { return String(s).replace(/[&<>"']/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]; }); };
  function ready(fn) { if (d.readyState !== 'loading') { fn(); } else { d.addEventListener('DOMContentLoaded', fn); } }
  var ICON = function (id) { return '<svg class="ic" aria-hidden="true"><use href="#' + id + '"/></svg>'; };
  function toast(msg) { var t = $('#toast'); if (!t) { return; } t.textContent = msg; t.classList.add('show'); clearTimeout(toast.t); toast.t = setTimeout(function () { t.classList.remove('show'); }, 2600); }

  ready(function () {
    var isPost = body.classList.contains('pt-item');
    var isHome = body.classList.contains('is-home');
    var article = $('.article');

    /* ---- Footer year ---- */
    var yr = $('#yr'); if (yr) { yr.textContent = new Date().getFullYear(); }

    /* ---- Header: shadow on scroll, mobile drawer, submenus ---- */
    var header = $('#site-header'), toggle = $('#nav-toggle'), up = $('#to-top'), bar = $('#progress');
    if (toggle && header) {
      toggle.addEventListener('click', function () {
        var open = header.classList.toggle('nav-open');
        toggle.setAttribute('aria-expanded', open ? 'true' : 'false');
        toggle.innerHTML = ICON(open ? 'i-close' : 'i-menu');
      });
    }
    $$('.main-nav a.has-sub').forEach(function (a) {
      a.addEventListener('click', function (e) {
        if (window.innerWidth <= 980) { e.preventDefault(); a.parentNode.classList.toggle('open'); }
      });
    });
    $$('.main-nav a').forEach(function (a) {
      try { if (!isHome && a.pathname === location.pathname && a.pathname !== '/' && !a.classList.contains('has-sub')) { a.classList.add('active'); } } catch (e) {}
    });
    var ticking = false;
    function onScroll() {
      ticking = false;
      var y = window.pageYOffset || root.scrollTop;
      if (header) { header.classList.toggle('is-stuck', y > 8); }
      if (up) { up.classList.toggle('show', y > 600); }
      if (bar && isPost) { var m = Math.max(1, root.scrollHeight - window.innerHeight); bar.style.transform = 'scaleX(' + Math.min(1, y / m).toFixed(4) + ')'; }
    }
    window.addEventListener('scroll', function () { if (!ticking) { ticking = true; requestAnimationFrame(onScroll); } }, { passive: true });
    onScroll();
    if (up) { up.addEventListener('click', function () { window.scrollTo({ top: 0, behavior: 'smooth' }); }); }

    /* ---- "New" badge on posts from the last 30 days ---- */
    $$('.tcard[data-date]').forEach(function (c) {
      var t = Date.parse(c.getAttribute('data-date'));
      if (t && Date.now() - t < 30 * 864e5 && !$('.badge-new', c)) { var b = d.createElement('span'); b.className = 'badge-new'; b.textContent = 'New'; c.insertBefore(b, c.firstChild); }
    });

    /* ---- Search / label page headings ---- */
    var at = $('#archive-title');
    if (at) {
      var q = new URLSearchParams(location.search).get('q');
      if (q) { at.textContent = 'Results for “' + q + '”'; }
      else if (/^\/search\/?$/.test(location.pathname)) { at.textContent = 'All Templates & Posts'; }
    }

    /* ---- Templates grid used by related posts ---- */
    function entryLink(e) { var l = (e.link || []).filter(function (x) { return x.rel === 'alternate'; })[0]; return l ? l.href : '#'; }
    function entryThumb(e, w) { var t = e.media$thumbnail; if (!t) { return ''; } return t.url.replace(/\/s\d+(-c)?\//, '/w' + w + '-h' + Math.round(w * 0.625) + '-c/'); }
    function cardHTML(e) {
      var href = entryLink(e), img = entryThumb(e, 480), title = e.title.$t;
      var tags = (e.category || []).slice(0, 3).map(function (c) { return '<span>' + esc(c.term) + '</span>'; }).join('');
      return '<article class="tcard" data-date="' + esc(e.published.$t) + '"><a class="tthumb" href="' + esc(href) + '">' +
        (img ? '<img src="' + esc(img) + '" alt="' + esc(title) + '" width="480" height="300" loading="lazy" decoding="async"/>' : '<span class="tthumb-empty">' + ICON('i-grid') + '</span>') +
        '</a><h2><a href="' + esc(href) + '">' + esc(title) + '</a></h2><div class="ttags">' + tags + '</div>' +
        '<a class="btn-dl" href="' + esc(href) + '">' + ICON('i-download') + ' Download</a></article>';
    }
    function getFeed(path) { return fetch(path).then(function (r) { return r.ok ? r.json() : Promise.reject(); }); }

    /* ---- Sidebar widgets from the public feed ---- */
    var lab = $('[data-widget="labels"]');
    if (lab) {
      getFeed('/feeds/posts/summary?alt=json&max-results=0').then(function (j) {
        var cats = (j.feed.category || []).slice(0, 24);
        lab.innerHTML = cats.map(function (c) { return '<a href="/search/label/' + encodeURIComponent(c.term) + '">' + esc(c.term) + '</a>'; }).join('');
      }).catch(function () { var w = lab.closest('.side-card'); if (w) { w.hidden = true; } });
    }
    var rec = $('[data-widget="recent"]');
    if (rec) {
      getFeed('/feeds/posts/summary?alt=json&max-results=5').then(function (j) {
        rec.innerHTML = (j.feed.entry || []).map(function (e) {
          var im = entryThumb(e, 128);
          return '<li>' + (im ? '<img src="' + esc(im) + '" alt="" width="64" height="48" loading="lazy"/>' : '') + '<a href="' + esc(entryLink(e)) + '">' + esc(e.title.$t) + '</a></li>';
        }).join('');
      }).catch(function () { var w = rec.closest('.side-card'); if (w) { w.hidden = true; } });
    }

    /* ---- Single post features ---- */
    if (article) {
      var pb = $('.post-body', article), title = txt($('h1', article));
      var words = txt(pb).split(' ').length, rt = $('.rt', article);
      if (rt) { rt.innerHTML = ICON('i-clock') + Math.max(1, Math.round(words / 200)) + ' min read'; }

      /* table of contents */
      var heads = $$('h2, h3', pb);
      if (heads.length >= 3) {
        var used = {}, items = heads.map(function (h) {
          var id = h.id || txt(h).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') || 'section';
          while (used[id]) { id += '-2'; } used[id] = 1; h.id = id;
          return '<li class="' + (h.tagName === 'H3' ? 'l3' : 'l2') + '"><a href="#' + id + '">' + esc(txt(h)) + '</a></li>';
        });
        var toc = d.createElement('nav'); toc.className = 'toc'; toc.setAttribute('aria-label', 'Table of contents');
        toc.innerHTML = '<strong>In this article</strong><ol>' + items.join('') + '</ol>';
        pb.insertBefore(toc, pb.firstChild);
      }

      /* copy buttons on code blocks */
      $$('pre', pb).forEach(function (pre) {
        var b = d.createElement('button'); b.type = 'button'; b.className = 'copy-code'; b.textContent = 'Copy';
        b.addEventListener('click', function () {
          var code = pre.querySelector('code') || pre;
          if (navigator.clipboard) { navigator.clipboard.writeText(code.innerText).then(function () { b.textContent = 'Copied'; setTimeout(function () { b.textContent = 'Copy'; }, 1600); }); }
        });
        pre.appendChild(b);
      });

      /* share buttons */
      var url = ($('link[rel="canonical"]') || {}).href || location.href.split('#')[0], enc = encodeURIComponent;
      var targets = { facebook: 'https://www.facebook.com/sharer/sharer.php?u=' + enc(url), x: 'https://twitter.com/intent/tweet?url=' + enc(url) + '&text=' + enc(title), whatsapp: 'https://wa.me/?text=' + enc(title + ' ' + url), linkedin: 'https://www.linkedin.com/sharing/share-offsite/?url=' + enc(url) };
      $$('[data-share]').forEach(function (a) { a.href = targets[a.getAttribute('data-share')] || '#'; });
      var cp = $('#copy-link'); if (cp) { cp.addEventListener('click', function () { if (navigator.clipboard) { navigator.clipboard.writeText(url).then(function () { toast('Link copied'); }); } }); }
      var ns = $('#native-share'); if (ns && navigator.share) { ns.hidden = false; ns.addEventListener('click', function () { navigator.share({ title: title, url: url }).catch(function () {}); }); }

      /* author initial */
      var ai = $('.author-ini', article), an = txt($('.author-name', article)); if (ai && an) { ai.textContent = an.charAt(0).toUpperCase(); }

      /* template details box (finds Download / Demo links written in the post) */
      var info = $('[data-widget="tpl-info"]');
      if (info) {
        var dl, dm;
        $$('a[href]', pb).forEach(function (a) {
          var t = txt(a);
          if (!dl && /download/i.test(t + ' ' + a.className)) { dl = a; }
          if (!dm && /(demo|preview)/i.test(t + ' ' + a.className)) { dm = a; }
        });
        var acts = $('.tpl-actions', info), facts = $('.tpl-facts', info), out = '';
        if (dl) { out += '<a class="btn btn-primary" href="' + esc(dl.href) + '" rel="noopener">' + ICON('i-download') + ' Download</a>'; }
        if (dm) { out += '<a class="btn btn-demo-s" href="' + esc(dm.href) + '" rel="noopener" target="_blank">' + ICON('i-play') + ' Live demo</a>'; }
        acts.innerHTML = out;
        var tags = $$('.post-tags a', article).map(txt).join(', ');
        facts.innerHTML = (tags ? '<li><span><b>Category:</b> ' + esc(tags) + '</span></li>' : '') + '<li><span><b>Published:</b> ' + esc(txt($('time.published', article))) + '</span></li>';
        info.hidden = false;
      }

      /* related templates */
      var rel = $('#related-posts');
      if (rel && rel.getAttribute('data-label')) {
        getFeed('/feeds/posts/summary/-/' + encodeURIComponent(rel.getAttribute('data-label')) + '?alt=json&max-results=5').then(function (j) {
          var list = (j.feed.entry || []).filter(function (e) { return entryLink(e).split('?')[0] !== url.split('?')[0]; }).slice(0, 3);
          if (list.length) { rel.innerHTML = '<h3>Related templates</h3><div class="tgrid">' + list.map(cardHTML).join('') + '</div>'; $$('.tcard[data-date]', rel).forEach(function (c) { var t = Date.parse(c.getAttribute('data-date')); if (t && Date.now() - t < 30 * 864e5) { var b = d.createElement('span'); b.className = 'badge-new'; b.textContent = 'New'; c.insertBefore(b, c.firstChild); } }); }
        }).catch(function () {});
      }
    }

    /* ---- Newsletter (FeedBurner) ---- */
    $$('.nl-form').forEach(function (f) {
      f.addEventListener('submit', function (e) {
        var id = f.getAttribute('data-feed'), em = $('input[type=email]', f);
        if (!em || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(em.value)) { e.preventDefault(); toast('Please enter a valid email address'); return; }
        if (!id || id === 'YOUR_FEEDBURNER_ID') { e.preventDefault(); toast('Newsletter is not set up yet'); return; }
        window.open('https://feedburner.google.com/fb/a/mailverifySubscribe?uri=' + encodeURIComponent(id), 'popupwindow', 'scrollbars=yes,width=550,height=520');
        toast('Check the pop-up to confirm your subscription');
      });
    });

    /* ---- Structured data: one @graph, built from what is on the page ---- */
    try {
      var canon = (($('link[rel="canonical"]') || {}).href || (location.origin + location.pathname)).split('#')[0];
      var homeUrl = location.origin + '/', site = ($('meta[property="og:site_name"]') || {}).content || d.title;
      var desc = ($('meta[name="description"]') || {}).content || '', ogImg = ($('meta[property="og:image"]') || {}).content || '';
      var orgId = homeUrl + '#organization', webId = homeUrl + '#website', pageId = canon + '#webpage';
      var same = $$('.ft-brand .social a[href^="http"]').map(function (a) { return a.href; });
      var g = [
        { '@type': 'Organization', '@id': orgId, name: site, url: homeUrl, sameAs: same.length ? same : undefined },
        { '@type': 'WebSite', '@id': webId, url: homeUrl, name: site, description: desc || undefined, publisher: { '@id': orgId }, inLanguage: root.lang || 'en',
          potentialAction: { '@type': 'SearchAction', target: { '@type': 'EntryPoint', urlTemplate: homeUrl + 'search?q={search_term_string}' }, 'query-input': 'required name=search_term_string' } },
        { '@type': isHome ? 'WebPage' : 'WebPage', '@id': pageId, url: canon, name: d.title, description: desc || undefined, isPartOf: { '@id': webId } }
      ];
      if (article) {
        var crumbs = $$('.crumbs li').map(function (li, i) { var a = $('a', li); return { '@type': 'ListItem', position: i + 1, name: txt(li), item: a ? a.href : canon }; });
        var pubT = ($('time.published', article) || {}).getAttribute ? $('time.published', article).getAttribute('datetime') : '';
        var modT = article.getAttribute('data-modified') || pubT, auName = txt($('.author-name', article)) || site, auUrl = article.getAttribute('data-author-url');
        var imgs = []; var fi = $('img', $('.post-body', article)); if (fi && fi.src) { imgs.push(fi.src); } if (ogImg && imgs.indexOf(ogImg) < 0) { imgs.push(ogImg); }
        var author = { '@type': 'Person', name: auName }; if (auUrl) { author.url = auUrl; }
        var posting = { '@type': 'BlogPosting', '@id': canon + '#article', mainEntityOfPage: { '@id': pageId }, headline: title.slice(0, 110), description: desc || undefined, url: canon, datePublished: pubT || undefined, dateModified: modT || undefined, author: author, publisher: { '@id': orgId }, image: imgs.length ? imgs : undefined, inLanguage: root.lang || 'en', isAccessibleForFree: true };
        var firstTag = txt($('.post-tags a', article)); if (firstTag) { posting.articleSection = firstTag; }
        g.push(posting);
        if (crumbs.length) { g.push({ '@type': 'BreadcrumbList', '@id': canon + '#breadcrumb', itemListElement: crumbs }); }
      } else {
        var li = $$('.tcard h2 a').map(function (a, i) { return { '@type': 'ListItem', position: i + 1, url: a.href, name: txt(a) }; });
        if (li.length) { g.push({ '@type': 'ItemList', name: isHome ? 'Latest templates' : (txt($('#archive-title')) || 'Templates'), itemListElement: li }); }
      }
      var sc = d.createElement('script'); sc.type = 'application/ld+json'; sc.id = 'ld-graph';
      sc.text = JSON.stringify({ '@context': 'https://schema.org', '@graph': g }).replace(/</g, '\\u003c');
      d.head.appendChild(sc);
    } catch (e) {}
  });
})();

//

//
(function () {
  'use strict';
  var w = window, d = document, root = d.documentElement, M = w.MOTION || {};
  var calm = !root.classList.contains('js');           /* reduced motion, or head script missing */
  w.__mo = 1;
  if (!('IntersectionObserver' in w) || !w.requestAnimationFrame) { root.classList.remove('js', 'pl'); root.classList.add('go'); calm = true; }

  var $ = function (s, c) { return (c || d).querySelector(s); };
  var $$ = function (s, c) { return Array.prototype.slice.call((c || d).querySelectorAll(s)); };
  var on = function (k) { return M[k] !== false; };
  var mq = function (q) { try { return !!w.matchMedia(q).matches; } catch (e) { return false; } };
  var raf = function (f) { return w.requestAnimationFrame(f); };
  var fine = mq('(hover:hover) and (pointer:fine)');
  var lite = !!((navigator.connection && navigator.connection.saveData) || (navigator.hardwareConcurrency && navigator.hardwareConcurrency <= 2));
  var body = d.body, isHome = body.classList.contains('is-home'), isPost = body.classList.contains('pt-item');
  var ICON = function (id) { return '<svg class="ic" aria-hidden="true"><use href="#' + id + '"/></svg>'; };
  var went = root.classList.contains('go'), queue = [];
  function whenGo(fn) { if (went) { fn(); } else { queue.push(fn); } }
  function release() { if (went) { return; } went = true; root.classList.add('go'); queue.splice(0).forEach(function (f) { try { f(); } catch (e) {} }); }
  function ready(fn) { if (d.readyState !== 'loading') { fn(); } else { d.addEventListener('DOMContentLoaded', fn); } }

  /* ---------- Intro: wait for load (min ~1.2 s), then wipe the curtain ---------- */
  function intro() {
    var pl = $('#preloader');
    if (!root.classList.contains('pl') || !pl) { release(); return; }
    var t0 = Date.now(), done = false;
    function finish() {
      if (done) { return; } done = true;
      setTimeout(function () {
        root.classList.add('pl-done');
        setTimeout(release, 380);
        setTimeout(function () { root.classList.remove('pl', 'pl-done'); if (pl.parentNode) { pl.parentNode.removeChild(pl); } }, 1000);
        try { sessionStorage.setItem('pos-intro', '1'); } catch (e) {}
      }, Math.max(0, 1250 - (Date.now() - t0)));
    }
    if (d.readyState === 'complete') { finish(); } else { w.addEventListener('load', finish); setTimeout(finish, 2000); }
  }

  /* ---------- Hero ---------- */
  var SHAPES = [['r', '52%', '7%', '46px'], ['q', '90%', '48%', '30px'], ['p', '47%', '76%', '26px'], ['t', '93%', '12%', '36px'], ['d', '3%', '84%', '14px'], ['d', '62%', '3%', '10px'], ['r', '1%', '46%', '22px']];
